export async function main(artifact_id: string | null, safi_context: string) {
  if (!safi_context) throw new Error("Missing SAFI user context");
  const query = artifact_id ? "?artifact_id=" + encodeURIComponent(artifact_id) : "";
  return await safiCall("/internal/context" + query, {
    headers: { "x-safi-context": safi_context }
  });
}

async function safiCall(path: string, init: RequestInit = {}) {
  const base = (process.env.SAFI_API_URL ?? "http://trusted_api:8080").replace(/\/+$/, "");
  const token = process.env.SAFI_INTERNAL_TOKEN;
  if (!token) throw new Error("SAFI_INTERNAL_TOKEN is not configured on the Windmill worker");
  const response = await fetch(base + path, {
    ...init,
    headers: {
      accept: "application/json",
      "x-internal-token": token,
      ...(init.headers ?? {})
    }
  });
  const text = await response.text();
  if (!response.ok) throw new Error("SAFI API " + response.status + ": " + text);
  return text ? JSON.parse(text) : null;
}

export async function main(title: string, safi_context: string) {
  if (!safi_context) throw new Error("Missing SAFI user context");
  return await safiCall("/internal/artifacts", {
    method: "POST",
    headers: { "content-type": "application/json", "x-safi-context": safi_context },
    body: JSON.stringify({ title: title || "Meeting checklist" })
  });
}

