export async function main(
  artifact_id: string,
  safi_context: string,
  op: string,
  text?: string,
  item_id?: string,
  done?: boolean,
  title?: string
) {
  if (!artifact_id) throw new Error("No Artifact is selected. Create one first.");
  if (!safi_context) throw new Error("Missing SAFI user context");

  const mutation: Record<string, unknown> = { op };
  if (text !== undefined && text !== null && text !== "") mutation.text = text;
  if (item_id !== undefined && item_id !== null && item_id !== "") mutation.itemId = item_id;
  if (done !== undefined && done !== null) mutation.done = done;
  if (title !== undefined && title !== null && title !== "") mutation.title = title;

  if (op === "set_title" && !mutation.title) throw new Error("set_title requires title");
  if ((op === "add_item" || op === "edit_item") && !mutation.text) throw new Error(op + " requires text");
  if ((op === "edit_item" || op === "set_item_done" || op === "remove_item") && !mutation.itemId) {
    throw new Error(op + " requires item_id. Call get_artifact first to read the current item ids.");
  }
  if (op === "set_item_done" && typeof mutation.done !== "boolean") {
    throw new Error("set_item_done requires done=true or done=false");
  }

  const current = await safiCall("/internal/context?artifact_id=" + encodeURIComponent(artifact_id), {
    headers: { "x-safi-context": safi_context }
  });

  const expectedVersion = current?.artifact?.version;
  if (!expectedVersion) throw new Error("Artifact was not found for this user");

  return await safiCall("/internal/artifacts/" + encodeURIComponent(artifact_id) + "/mutate", {
    method: "POST",
    headers: { "content-type": "application/json", "x-safi-context": safi_context },
    body: JSON.stringify({ expectedVersion, mutation })
  });
}

