export async function main(
  artifact_id: string,
  safi_context: string,
  from_date?: string,
  to_date?: string,
  timezone?: string
) {
  if (!artifact_id) throw new Error("No Artifact is selected. Create one first.");
  if (!safi_context) throw new Error("Missing SAFI user context");

  const from = from_date || new Date().toISOString().slice(0, 10);
  const to = to_date || new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10);
  const tz = timezone || "UTC";
  const query = new URLSearchParams({ artifact_id, from, to, tz });

  const result = await safiCall("/internal/calnode/slots?" + query.toString(), {
    headers: { "x-safi-context": safi_context }
  });

  return {
    eventTypeSlug: result.eventTypeSlug,
    timezone: result.timezone,
    degraded: result.degraded,
    slots: (result.slots ?? []).slice(0, 20),
    booking_note: "These are real Calnode slots. Do not book them. Tell the user to select one in the Artifact pane and click Approve and book."
  };
}

